<?php $kind=get_post_type()==='gmr_event'?(gmr_theme_event_types(get_the_ID())?:'Agenda'):(get_post_type()==='gmr_media_gallery'?'Multimedia':'Noticias');?>
<article <?php post_class('gmr-story-card');?>><a href="<?php the_permalink();?>"><div class="gmr-story-card__image"><?php the_post_thumbnail('large');?></div><div class="gmr-story-card__body"><div class="gmr-story-meta"><span><?php echo esc_html($kind);?></span><span><?php echo esc_html(get_post_type()==='gmr_event'?gmr_theme_event_date(get_the_ID()):get_the_date());?></span></div><h2><?php the_title();?></h2><?php if(has_excerpt()):?><p><?php echo esc_html(get_the_excerpt());?></p><?php endif;?></div></a></article>
